  check(b.getClass()==com.hbm.blocks.generic.BlockOre.class&&!((com.hbm.blocks.generic.BlockOre)b).allowFortune,"actual titanium owner/noFortune constructor");check(b.getBlockState().getValidStates().size()==16&&b.getMetaFromState(b.getDefaultState())==0,"actual native state domain/default");check(b.getDefaultState().getMaterial()==net.minecraft.block.material.Material.IRON&&b.getBlockHardness(b.getDefaultState(),w,BlockPos.ORIGIN)==5&&b.getExplosionResistance(null)==6,"actual titanium material/hardness/resistance");
